122	     * @param ownerFieldsDto the submitted owner fields
123	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
124	     */
125	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
126	        List<String> invalidFields = new ArrayList<>();
127	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
128	            invalidFields.add("firstName");
129	        }
130	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
