139	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
140	            invalidFields.add("telephone");
141	        }
142	        if (!invalidFields.isEmpty()) {
143	            throw new InvalidOwnerFieldsException(invalidFields);
144	        }
