156	    private String normalizeTelephone(String telephone) {
157	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
158	        if (digits.length() != 10) {
159	            throw new InvalidOwnerFieldsException(List.of("telephone"));
160	        }
161	        return digits;
